<?php if (!defined('ABSPATH')) { exit; } ?>
<!doctype html><html <?php language_attributes(); ?>><head>
<meta charset="<?php bloginfo('charset'); ?>"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?php esc_html_e('Reset password', 'kklidi-members'); ?></title><?php wp_head(); ?>
</head><body <?php body_class('kklidi-members-page kklidi-members-page--password-reset'); ?>><?php wp_body_open(); ?>
<main class="kklidi-members-main"><section class="kklidi-members-card" aria-labelledby="kklidi-members-page-title"><header class="kklidi-members-header"><p class="kklidi-members-eyebrow"><?php echo esc_html(get_bloginfo('name')); ?></p><h1 id="kklidi-members-page-title"><?php esc_html_e('Reset password', 'kklidi-members'); ?></h1><p><?php esc_html_e('WordPress Core securely issues and verifies each reset link.', 'kklidi-members'); ?></p></header>
<?php if ($message !== '') : ?><p class="kklidi-members-notice<?php echo $message_type === 'error' ? ' kklidi-members-notice--error' : ''; ?>" role="<?php echo $message_type === 'error' ? 'alert' : 'status'; ?>"><?php echo esc_html($message); ?></p><?php endif; ?>
<?php if ($field_errors !== array()) : ?><div class="kklidi-members-field-errors" role="alert"><p><?php esc_html_e('Please correct the highlighted fields.', 'kklidi-members'); ?></p><ul><?php foreach ($field_errors as $field) : ?><li><a href="#kklidi-members-reset-<?php echo esc_attr($field); ?>"><?php esc_html_e('Use at least 12 characters and enter the same password twice.', 'kklidi-members'); ?></a></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if ($mode === 'request') : ?><form class="kklidi-members-form" method="post" action="<?php echo esc_url($action_url); ?>"><input type="hidden" name="kklidi_members_password_reset" value="1"><input type="hidden" name="reset_action" value="request"><?php wp_nonce_field('kklidi_members_password_reset_request', '_kklidi_members_password_reset_nonce'); ?><?php echo $request_fields; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- generated escaped fields. ?><label class="kklidi-members-field" for="kklidi-members-reset-login"><?php esc_html_e('Username or email', 'kklidi-members'); ?><input id="kklidi-members-reset-login" name="user_login" autocomplete="username" value="<?php echo esc_attr($identifier); ?>" required></label><button class="kklidi-members-button" type="submit"><?php esc_html_e('Send password reset link', 'kklidi-members'); ?></button></form>
<?php elseif ($mode === 'reset' && $reset_user instanceof WP_User) : ?><form class="kklidi-members-form" method="post" action="<?php echo esc_url($action_url); ?>"><input type="hidden" name="kklidi_members_password_reset" value="1"><input type="hidden" name="reset_action" value="complete"><input type="hidden" name="key" value="<?php echo esc_attr($key); ?>"><input type="hidden" name="login" value="<?php echo esc_attr($login); ?>"><?php wp_nonce_field('kklidi_members_password_reset_complete', '_kklidi_members_password_reset_complete_nonce'); ?><?php echo $complete_fields; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- generated escaped fields. ?><div class="kklidi-members-field"><label for="kklidi-members-reset-new-password"><?php esc_html_e('New password', 'kklidi-members'); ?></label><div class="kklidi-members-password-control"><input id="kklidi-members-reset-new-password" type="password" name="new_password" autocomplete="new-password" minlength="12" required data-kklidi-members-password<?php echo in_array('new_password', $field_errors, true) ? ' aria-invalid="true" aria-describedby="kklidi-members-reset-new-password-error"' : ''; ?>><button class="kklidi-members-password-toggle" type="button" data-kklidi-members-password-toggle aria-controls="kklidi-members-reset-new-password" aria-pressed="false" data-show-label="<?php esc_attr_e('Show password', 'kklidi-members'); ?>" data-hide-label="<?php esc_attr_e('Hide password', 'kklidi-members'); ?>"><?php esc_html_e('Show password', 'kklidi-members'); ?></button></div><?php if (in_array('new_password', $field_errors, true)) : ?><span class="kklidi-members-field-error" id="kklidi-members-reset-new-password-error"><?php esc_html_e('Use at least 12 characters.', 'kklidi-members'); ?></span><?php endif; ?></div><div class="kklidi-members-field"><label for="kklidi-members-reset-new-password-confirm"><?php esc_html_e('Confirm new password', 'kklidi-members'); ?></label><div class="kklidi-members-password-control"><input id="kklidi-members-reset-new-password-confirm" type="password" name="new_password_confirm" autocomplete="new-password" minlength="12" required data-kklidi-members-password<?php echo in_array('new_password_confirm', $field_errors, true) ? ' aria-invalid="true" aria-describedby="kklidi-members-reset-new-password-confirm-error"' : ''; ?>><button class="kklidi-members-password-toggle" type="button" data-kklidi-members-password-toggle aria-controls="kklidi-members-reset-new-password-confirm" aria-pressed="false" data-show-label="<?php esc_attr_e('Show password', 'kklidi-members'); ?>" data-hide-label="<?php esc_attr_e('Hide password', 'kklidi-members'); ?>"><?php esc_html_e('Show password', 'kklidi-members'); ?></button></div><?php if (in_array('new_password_confirm', $field_errors, true)) : ?><span class="kklidi-members-field-error" id="kklidi-members-reset-new-password-confirm-error"><?php esc_html_e('Enter the same password again.', 'kklidi-members'); ?></span><?php endif; ?></div><button class="kklidi-members-button" type="submit"><?php esc_html_e('Reset password', 'kklidi-members'); ?></button></form><?php endif; ?>
<nav class="kklidi-members-form-links" aria-label="<?php esc_attr_e('Password reset help', 'kklidi-members'); ?>"><?php if ($mode === 'invalid') : ?><a href="<?php echo esc_url($action_url); ?>"><?php esc_html_e('Request a new reset link', 'kklidi-members'); ?></a><?php endif; ?><a href="<?php echo esc_url($login_url); ?>"><?php esc_html_e('Back to login', 'kklidi-members'); ?></a></nav>
</section></main><?php wp_footer(); ?></body></html>
